  "anomalies": [
    {
      "category": "polarity",
      "components": ["D3", "D7"],
      "pins": ["D3.1", "D3.3", "D7.1", "D7.3", "U2.30", "U2.31", "J1.3", "J2.3"],
      "nets": ["NET0003", "NET0014", "Net-(D3-A)", "Net-(D7-A)"],
      "observed": "Both fan-tach signals reach their MCU inputs through series diodes oriented with the cathode toward the fan connector and the anode toward the MCU. D7 has its cathode on NET0003 with J1.3 and its anode on Net-(D7-A) with U2.31; D3 has its cathode on NET0014 with J2.3 and its anode on Net-(D3-A) with U2.30.",
      "expected": "Fan tach transitions, including the low pulses typically produced by open-collector tach outputs, must be able to reach the MCU inputs so the controller can detect fan stalls. The series diodes should not block those transitions.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"9\") (name \"NET0003\") ... (node (ref \"D7\") (pin \"3\") (pinfunction \"K\")) (node (ref \"J1\") (pin \"3\") ...))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"18\") (name \"Net-(D7-A)\") ... (node (ref \"D7\") (pin \"1\") (pinfunction \"A\")) ... (node (ref \"U2\") (pin \"31\") (pinfunction \"GPIO21/U0TXD\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"14\") (name \"NET0012\") ... (node (ref \"D3\") (pin \"3\") (pinfunction \"K\")) (node (ref \"J2\") (pin \"3\") ...))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"17\") (name \"Net-(D3-A)\") ... (node (ref \"D3\") (pin \"1\") (pinfunction \"A\")) ... (node (ref \"U2\") (pin \"30\") (pinfunction \"GPIO20/U0RXD\")))"
        },
        {
          "source": "spec",
          "quote": "Monitors 2 fan tachometers ... and raises a run fault if a fan stalls."
        }
      ],
      "impact": "When a tach output pulls its connector signal low, the diode is reverse-biased, so that low transition is not conveyed to the MCU input. Fan speed/stall monitoring may therefore fail or report incorrect fan status.",
      "confidence": 0.94
    }
  ],
  "summary": "The two fan-tach channels have series diodes oriented to block low-going tach pulses from reaching the MCU. This conflicts with the specified fan-stall monitoring and is likely to make that monitoring unreliable."
}

